<script>
(()=>{const shell=document.querySelector('.fm-shell');if(!shell)return;const csrf=document.querySelector('meta[name="csrf-token"]')?.content||@json(csrf_token());const uploadEndpoint=@json(route('admin.documents.chunks'));const currentUrl=@json(request()->fullUrl());const folderId=shell.dataset.folder||'';const $=id=>document.getElementById(id);document.querySelectorAll('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog')?.close()));document.querySelectorAll('[data-open-upload]').forEach(b=>b.addEventListener('click',()=>$('fm-upload-dialog').showModal()));document.querySelectorAll('[data-open-folder]').forEach(b=>b.addEventListener('click',()=>$('fm-folder-dialog').showModal()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close()}));
const actionDialog=$('fm-action-dialog'),actionForm=$('fm-action-form'),actionFields=$('fm-action-fields'),actionTitle=$('fm-action-title'),actionDescription=$('fm-action-description'),actionSubmit=$('fm-action-submit');const folders=@json($allFolders->map(fn($f)=>['id'=>$f->id,'name'=>$f->name])->values());const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const options=(name,current,exclude)=>'<label class="fm-field"><span>Destination</span><select name="'+name+'"><option value="">My Files (root)</option>'+folders.filter(f=>String(f.id)!==String(exclude||'')).map(f=>'<option value="'+f.id+'" '+(String(f.id)===String(current||'')?'selected':'')+'>'+esc(f.name)+'</option>').join('')+'</select></label>';
const openAction=(type,b)=>{actionForm.action=b.dataset.url;actionFields.innerHTML='';actionSubmit.className='fm-btn fm-btn-primary';actionSubmit.disabled=false;if(type==='rename-folder'||type==='rename-file'){actionTitle.textContent='Rename '+(type.endsWith('folder')?'folder':'file');actionDescription.textContent='Enter the new name. File extensions are preserved automatically.';actionFields.innerHTML='<label class="fm-field"><span>Name</span><input name="name" maxlength="255" value="'+esc(b.dataset.name)+'" required autofocus></label>';actionSubmit.textContent='Save changes';}else if(type==='move-folder'||type==='move-file'){actionTitle.textContent='Move '+(type.endsWith('folder')?'folder':'file');actionDescription.textContent='Choose a safe destination.';actionFields.innerHTML=options(type.endsWith('folder')?'parent_id':'folder_id',type.endsWith('folder')?'':b.dataset.folder,type.endsWith('folder')?b.dataset.id:'');actionSubmit.textContent='Move';}else if(type==='copy-folder'||type==='copy-file'){actionTitle.textContent='Copy '+(type.endsWith('folder')?'folder':'file');actionDescription.textContent='A separate copy will be created.';actionFields.innerHTML=options(type.endsWith('folder')?'parent_id':'folder_id','',type.endsWith('folder')?b.dataset.id:'');actionSubmit.textContent='Create copy';}else{actionTitle.textContent='Delete permanently?';actionDescription.textContent='This action cannot be undone.';actionFields.innerHTML='<div class="fm-dialog-note"><i class="fa-solid fa-triangle-exclamation"></i><span>“'+esc(b.dataset.name||'This item')+'” will be permanently removed from private storage.</span></div>';actionSubmit.textContent='Delete permanently';actionSubmit.className='fm-btn fm-danger';}actionDialog.showModal();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;b.closest('details')?.removeAttribute('open');if(a==='share'){openShare(b);return;}e.preventDefault();openAction(a,b)});
async function post(url,data={}){const r=await fetch(url,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json','Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(data)});const text=await r.text();let j={};try{j=text?JSON.parse(text):{}}catch{}if(!r.ok)throw new Error(j.message||j.error||'Request failed ('+r.status+').');return j;}
async function refreshFiles(){const url=new URL(currentUrl);url.searchParams.set('_fm',Date.now());try{const r=await fetch(url,{headers:{'X-Requested-With':'XMLHttpRequest','Accept':'text/html'}});if(!r.ok)return;const html=await r.text();const doc=new DOMParser().parseFromString(html,'text/html');const incoming=doc.querySelector('#file-list'),current=$('file-list');if(incoming&&current)current.replaceWith(incoming)}catch(e){}}
const shareDialog=$('fm-share-dialog'),shareBody=$('fm-share-body'),shareName=$('fm-share-name');async function openShare(b){shareName.textContent=b.dataset.name;shareDialog.showModal();if(b.dataset.active==='1'){shareBody.innerHTML='<div class="fm-share-card"><div class="fm-share-status"><i class="fa-solid fa-circle-check"></i> Link is active.</div><div class="fm-share-url"><input readonly value="'+esc(b.dataset.publicUrl)+'"><button type="button" id="fm-copy-share"><i class="fa-regular fa-copy"></i></button></div><div class="fm-share-actions"><button type="button" class="fm-btn" data-close-dialog>Done</button><button type="button" class="fm-btn fm-danger" id="fm-revoke-share">Revoke link</button></div></div>';$('fm-copy-share').onclick=()=>navigator.clipboard?.writeText(b.dataset.publicUrl);$('fm-revoke-share').onclick=async()=>{try{await post(b.dataset.unshareUrl);shareDialog.close();await refreshFiles()}catch(e){alert(e.message)}};}else{shareBody.innerHTML='<div class="fm-share-card"><p style="color:var(--muted);font-size:12px">Create a secure, non-guessable download link. You can revoke it later.</p><div class="fm-share-actions"><button type="button" class="fm-btn" data-close-dialog>Cancel</button><button type="button" class="fm-btn fm-btn-primary" id="fm-create-share">Create link</button></div></div>';$('fm-create-share').onclick=async()=>{try{await post(b.dataset.shareUrl);shareDialog.close();await refreshFiles()}catch(e){alert(e.message)}};}}
const input=$('file-upload-input'),drop=$('fm-dropzone'),queue=$('fm-upload-queue'),start=$('fm-start-upload');let files=[];const render=()=>{queue.innerHTML='';files.forEach((f,i)=>{const r=document.createElement('div');r.className='fm-upload-item';r.dataset.index=i;r.innerHTML='<div class="fm-upload-line"><span class="fm-upload-name" title="'+esc(f.name)+'">'+esc(f.name)+'</span><span class="fm-upload-status">Ready</span></div><div class="fm-upload-track"><span></span></div>';queue.appendChild(r)})};input?.addEventListener('change',()=>{files=[...input.files];render()});['dragenter','dragover'].forEach(x=>drop?.addEventListener(x,e=>{e.preventDefault();drop.classList.add('is-dragging')}));['dragleave','drop'].forEach(x=>drop?.addEventListener(x,e=>{e.preventDefault();drop.classList.remove('is-dragging')}));drop?.addEventListener('drop',e=>{files=[...e.dataTransfer.files];render()});const sleep=ms=>new Promise(r=>setTimeout(r,ms));async function retry(url,opt){let last;for(let n=1;n<=3;n++){try{const r=await fetch(url,opt);if(r.ok||![408,413,429,500,502,503,504].includes(r.status))return r;last=new Error('Temporary server error ('+r.status+').')}catch(e){last=e}if(n<3)await sleep(n*500)}throw last||new Error('Upload request failed.')}async function json(r){const t=await r.text();let j={};try{j=t?JSON.parse(t):{}}catch{}if(!r.ok)throw new Error(j.message||j.error||'Upload failed ('+r.status+').');return j}async function uploadOne(file,row){const s=row.querySelector('.fm-upload-status'),bar=row.querySelector('.fm-upload-track span'),set=(p,t)=>{bar.style.width=p+'%';s.textContent=t};set(0,'Preparing…');const p=new URLSearchParams({filename:file.name,size:String(file.size),mime_type:file.type||'application/octet-stream'});if(folderId)p.set('folder_id',folderId);const begin=await json(await retry(uploadEndpoint,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json','Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:p.toString()}));const id=begin.upload_id,chunk=Math.min(65536,Number(begin.chunk_size)||65536);if(!id)throw new Error('Upload session was not created.');const total=Math.ceil(file.size/chunk);for(let i=0;i<total;i++){const off=i*chunk,blob=file.slice(off,Math.min(off+chunk,file.size));await json(await retry(uploadEndpoint,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json','Content-Type':'application/octet-stream','X-Upload-Id':id,'X-Chunk-Index':String(i),'X-Chunk-Offset':String(off),'X-Chunk-Length':String(blob.size)},body:blob}));set(Math.min(98,Math.round(((off+blob.size)/file.size)*100)),Math.min(98,Math.round(((off+blob.size)/file.size)*100))+'%')}set(99,'Finalizing…');await json(await retry(uploadEndpoint,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json','Content-Type':'application/x-www-form-urlencoded;charset=UTF-8','X-Upload-Id':id},body:'finalize=1'}));set(100,'Complete');row.classList.add('is-done')}
start?.addEventListener('click',async()=>{if(!files.length){input?.click();return}start.disabled=true;for(let i=0;i<files.length;i++){const row=queue.querySelector('[data-index="'+i+'"]');try{await uploadOne(files[i],row)}catch(e){row.classList.add('is-error');row.querySelector('.fm-upload-status').textContent=e.message||'Upload failed'}}start.disabled=false;await refreshFiles()});
actionForm?.addEventListener('submit',async e=>{e.preventDefault();actionSubmit.disabled=true;try{await post(actionForm.action,Object.fromEntries(new FormData(actionForm)));actionDialog.close();await refreshFiles()}catch(err){actionSubmit.disabled=false;alert(err.message||'Action failed.')}});
})();
</script>
@endpush
